#pragma once
#include <pagmo/algorithm.hpp>
#include <pagmo/algorithms/sade.hpp>
#include <pagmo/algorithms/cmaes.hpp>
#include <pagmo/algorithms/sga.hpp>
#include <pagmo/algorithms/nsga2.hpp>
#include <pagmo/algorithms/cstrs_self_adaptive.hpp>
#include <nlohmann/json.hpp>
#include <cmath>
#include <locale>
#include <sstream>
#include <stdexcept>
namespace penta::evolution::session_detail {
using Json=nlohmann::json;
inline void require(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
inline std::uint64_t boundedInteger(const Json& value,std::uint64_t maximum){require(value.is_number_unsigned()||(value.is_number_integer()&&value.get<std::int64_t>()>=0),"Checkpoint counters require nonnegative integers.");const auto count=value.get<std::uint64_t>();require(count<=maximum,"Checkpoint counter exceeds its checked bound.");return count;}
inline double finiteNumber(const Json& value){require(value.is_number(),"Checkpoint numeric state must contain numbers.");const double number=value.get<double>();require(std::isfinite(number)&&std::abs(number)<=1e100,"Checkpoint adaptation state is nonfinite or exceeds its numeric bound.");return number;}
inline Json vectorState(const std::vector<double>& values){Json out=Json::array();for(double value:values){require(std::isfinite(value)&&std::abs(value)<=1e100,"Native adaptation state exceeded its checkpoint bound.");out.push_back(value);}return out;}
inline std::vector<double> checkedVector(const Json& value,std::size_t expected){require(value.is_array()&&value.size()==expected,"Checkpoint vector dimension changed.");std::vector<double> output;output.reserve(expected);for(const auto& number:value)output.push_back(finiteNumber(number));return output;}
template<class Engine>Json engineState(const Engine& engine){std::ostringstream text;text.imbue(std::locale::classic());text<<engine;return text.str();}
template<class Engine>void restoreEngine(Engine& engine,const Json& value){require(value.is_string(),"Checkpoint RNG state must be text.");const auto& text=value.get_ref<const std::string&>();require(text.size()<=32768,"Checkpoint RNG state exceeds its fixed-engine bound.");std::istringstream tokens(text);tokens.imbue(std::locale::classic());bool nonzero=false;for(std::size_t i=0;i<Engine::state_size;++i){std::uint64_t word=0;tokens>>word;require(!tokens.fail()&&word<=Engine::max(),"Invalid fixed-size RNG state word.");nonzero=nonzero||word!=0;}std::uint64_t index=0;tokens>>index;require(!tokens.fail()&&index<=Engine::state_size&&nonzero,"Invalid fixed-size RNG state index or zero state.");tokens>>std::ws;require(tokens.eof(),"Trailing data in fixed-size RNG state.");std::istringstream input(text);input.imbue(std::locale::classic());Engine restored;input>>restored;require(!input.fail(),"Invalid fixed-size RNG state.");engine=restored;}
struct StateAccess {
    static Json vector(const Eigen::VectorXd& values){Json data=Json::array();for(Eigen::Index i=0;i<values.size();++i)data.push_back(finiteNumber(Json(values[i])));return data;}
    static Eigen::VectorXd loadVector(const Json& value,std::size_t n){const auto data=checkedVector(value,n);Eigen::VectorXd output(static_cast<Eigen::Index>(n));for(std::size_t i=0;i<n;++i)output[static_cast<Eigen::Index>(i)]=data[i];return output;}
    static Json matrix(const Eigen::MatrixXd& values){Json data=Json::array();for(Eigen::Index row=0;row<values.rows();++row)for(Eigen::Index col=0;col<values.cols();++col)data.push_back(finiteNumber(Json(values(row,col))));return {{"rows",values.rows()},{"columns",values.cols()},{"values",std::move(data)}};}
    static Eigen::MatrixXd loadMatrix(const Json& value,std::size_t n){require(value.is_object()&&boundedInteger(value.at("rows"),128)==n&&boundedInteger(value.at("columns"),128)==n,"Checkpoint matrix dimension differs from the checked problem.");const auto data=checkedVector(value.at("values"),n*n);Eigen::MatrixXd output(static_cast<Eigen::Index>(n),static_cast<Eigen::Index>(n));for(std::size_t row=0;row<n;++row)for(std::size_t col=0;col<n;++col)output(static_cast<Eigen::Index>(row),static_cast<Eigen::Index>(col))=data[row*n+col];return output;}
    static Json saveBase(const pagmo::algorithm& algorithm,unsigned code,std::size_t n,std::size_t population){
        if(code==1||code==2){const auto* a=algorithm.extract<pagmo::sade>();require(a,"Native algorithm type differs from its checked selection.");require((a->m_F.empty()||a->m_F.size()==population)&&a->m_F.size()==a->m_CR.size(),"Native SADE memory shape changed.");return {{"engine",engineState(a->m_e)},{"F",vectorState(a->m_F)},{"CR",vectorState(a->m_CR)}};}
        if(code==3){const auto* a=algorithm.extract<pagmo::cmaes>();require(a,"Native CMA-ES type differs from its checked selection.");const bool warm=!a->newpop.empty();Json result{{"engine",engineState(a->m_e)},{"warm",warm}};if(!warm)return result;require(a->newpop.size()==population&&a->mean.size()==static_cast<Eigen::Index>(n),"Native CMA-ES memory shape changed.");Json offspring=Json::array();for(const auto& child:a->newpop){require(child.size()==static_cast<Eigen::Index>(n),"Native CMA-ES offspring dimension changed.");offspring.push_back(vector(child));}result["sigma"]=finiteNumber(Json(a->sigma));result["mean"]=vector(a->mean);result["newpop"]=std::move(offspring);result["B"]=matrix(a->B);result["D"]=matrix(a->D);result["C"]=matrix(a->C);result["invsqrtC"]=matrix(a->invsqrtC);result["pc"]=vector(a->pc);result["ps"]=vector(a->ps);result["counteval"]=a->counteval;result["eigeneval"]=a->eigeneval;return result;}
        if(code==4){const auto* a=algorithm.extract<pagmo::sga>();require(a,"Native GA type differs from its checked selection.");return {{"engine",engineState(a->m_e)}};}
        const auto* a=algorithm.extract<pagmo::nsga2>();require(a,"Native NSGA-II type differs from its checked selection.");return {{"engine",engineState(a->m_e)}};
    }
    static void loadBase(pagmo::algorithm& algorithm,const Json& state,unsigned code,std::size_t n,std::size_t population){
        require(n>=1&&n<=128&&population>=8&&population<=4096&&state.is_object(),"Invalid bounded adaptation-state dimensions.");
        if(code==1||code==2){auto* a=algorithm.extract<pagmo::sade>();require(a,"Unexpected SADE state type.");const auto& f=state.at("F");require(f.is_array()&&(f.empty()||f.size()==population),"Invalid SADE adaptation length.");auto F=checkedVector(f,f.size()),CR=checkedVector(state.at("CR"),f.size());restoreEngine(a->m_e,state.at("engine"));a->m_F=std::move(F);a->m_CR=std::move(CR);return;}
        if(code==3){auto* a=algorithm.extract<pagmo::cmaes>();require(a,"Unexpected CMA-ES state type.");restoreEngine(a->m_e,state.at("engine"));require(state.at("warm").is_boolean(),"Invalid CMA-ES initialization flag.");if(!state.at("warm").get<bool>())return;const double sigma=finiteNumber(state.at("sigma"));require(sigma>0,"CMA-ES checkpoint sigma must be positive.");const auto& children=state.at("newpop");require(children.is_array()&&children.size()==population,"CMA-ES offspring count changed.");std::vector<Eigen::VectorXd> newpop;newpop.reserve(population);for(const auto& child:children)newpop.push_back(loadVector(child,n));a->mean=loadVector(state.at("mean"),n);a->variation=Eigen::VectorXd::Zero(static_cast<Eigen::Index>(n));a->pc=loadVector(state.at("pc"),n);a->ps=loadVector(state.at("ps"),n);a->B=loadMatrix(state.at("B"),n);a->D=loadMatrix(state.at("D"),n);a->C=loadMatrix(state.at("C"),n);a->invsqrtC=loadMatrix(state.at("invsqrtC"),n);a->counteval=boundedInteger(state.at("counteval"),100000000);a->eigeneval=boundedInteger(state.at("eigeneval"),a->counteval);a->sigma=sigma;a->newpop=std::move(newpop);return;}
        if(code==4){auto* a=algorithm.extract<pagmo::sga>();require(a,"Unexpected GA state type.");restoreEngine(a->m_e,state.at("engine"));return;}
        auto* a=algorithm.extract<pagmo::nsga2>();require(a,"Unexpected NSGA-II state type.");restoreEngine(a->m_e,state.at("engine"));
    }
    static Json save(const pagmo::algorithm& algorithm,unsigned code,std::size_t n,std::size_t population,bool constrained){if(!constrained)return saveBase(algorithm,code,n,population);const auto* wrapper=algorithm.extract<pagmo::cstrs_self_adaptive>();require(wrapper,"Native constraint adapter type changed.");return {{"engine",engineState(wrapper->m_e)},{"inner",saveBase(wrapper->m_algorithm,code,n,population)}};}
    static void load(pagmo::algorithm& algorithm,const Json& state,unsigned code,std::size_t n,std::size_t population,bool constrained){if(!constrained){loadBase(algorithm,state,code,n,population);return;}auto* wrapper=algorithm.extract<pagmo::cstrs_self_adaptive>();require(wrapper,"Unexpected constraint adapter type.");restoreEngine(wrapper->m_e,state.at("engine"));loadBase(wrapper->m_algorithm,state.at("inner"),code,n,population);}
};
}
